import { create } from "zustand";
import { v4 as uuidv4 } from "uuid";
import { toast } from "sonner";

export interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  timestamp: Date;
  total_tokens?: number;
}

export interface ChatItem {
  id: string;
  title: string;
  messages: Message[];
  total_tokens: number;
  createdAt: Date;
  updatedAt: Date;
}

interface ChatStore {
  chats: ChatItem[];
  createChat: () => Promise<ChatItem | undefined>;
  updateChat: (id: string, title: string) => void;
  deleteChat: (id: string, onSuccess?: () => void) => Promise<void>;
  getChatById: (id: string) => ChatItem | undefined;
  addMessage: (chatId: string, role: "user" | "assistant", content: string) => Promise<void>;
  fetchChats: () => Promise<void>;
  clearHistory: () => Promise<void>;
  isLoading: boolean;
}

export const useChatStore = create<ChatStore>((set, get) => ({
  chats: [],
  isLoading: true,

  createChat: async () => {
    try {
      const response = await fetch("http://localhost:8000/api/chat/history", {
        method: "POST",
      });
      if (!response.ok) throw new Error("Failed to create chat on server");

      const chatData = await response.json();
      const newChat: ChatItem = {
        id: chatData.id,
        title: chatData.title,
        messages: [],
        total_tokens: 0,
        createdAt: new Date(chatData.created_at),
        updatedAt: new Date(chatData.updated_at),
      };

      set((state) => ({
        chats: [newChat, ...state.chats],
      }));
      return newChat;
    } catch (error) {
      console.error("Failed to create chat:", error);
      toast.error("Failed to start a new chat session.");
      return undefined;
    }
  },

  updateChat: (id: string, title: string) => {
    set((state) => ({
      chats: state.chats.map((chat) =>
        chat.id === id ? { ...chat, title, updatedAt: new Date() } : chat
      ),
    }));
  },

  deleteChat: async (id: string, onSuccess?: () => void) => {
    try {
      const response = await fetch(`http://localhost:8000/api/chat/history/${id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Failed to delete chat on server");

      set((state) => ({
        chats: state.chats.filter((chat) => chat.id !== id),
      }));
      toast.success("Chat deleted successfully");

      // Call the callback to handle navigation etc.
      onSuccess?.();
    } catch (error) {
      console.error("Failed to delete chat:", error);
      toast.error("Failed to delete chat history.");
    }
  },

  getChatById: (id: string) => {
    return get().chats.find((chat) => chat.id === id);
  },

  addMessage: async (chatId: string, role: "user" | "assistant", content: string) => {
    const newMessage: Message = {
      id: uuidv4(),
      role,
      content,
      timestamp: new Date(),
    };

    set((state) => ({
      chats: state.chats.map((chat) =>
        chat.id === chatId
          ? {
            ...chat,
            messages: [...chat.messages, newMessage],
            updatedAt: new Date(),
          }
          : chat
      ),
    }));

    if (role === "user") {
      const activeChat = get().chats.find(c => c.id === chatId);
      if (!activeChat) return;

      try {
        const response = await fetch("http://localhost:8000/api/chat/stream", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            prompt: content,
            chat_id: chatId,
            model: "gpt-5-mini"
          }),
        });

        if (!response.ok) {
          const errorData = await response.json().catch(() => ({ detail: "Unknown server error" }));
          throw new Error(errorData.detail || "Failed to connect to AI server");
        }

        const reader = response.body?.getReader();
        if (!reader) return;

        const assistantMessageId = uuidv4();
        let assistantContent = "";

        set((state) => ({
          chats: state.chats.map((chat) =>
            chat.id === chatId
              ? {
                ...chat,
                messages: [
                  ...chat.messages,
                  { id: assistantMessageId, role: "assistant", content: "", timestamp: new Date() }
                ],
              }
              : chat
          ),
        }));

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const chunk = new TextDecoder().decode(value);

          if (chunk.includes("🚨 Error:")) {
            toast.error(chunk.replace("🚨", "").trim());
          }

          assistantContent += chunk;

          set((state) => ({
            chats: state.chats.map((chat) =>
              chat.id === chatId
                ? {
                  ...chat,
                  messages: chat.messages.map(m =>
                    m.id === assistantMessageId ? { ...m, content: assistantContent } : m
                  ),
                }
                : chat
            ),
          }));
        }

        await get().fetchChats();

      } catch (error: any) {
        console.error("Streaming error:", error);
        toast.error(error.message || "Unable to reach the AI server.");

        set((state) => ({
          chats: state.chats.map((chat) =>
            chat.id === chatId
              ? {
                ...chat,
                messages: [
                  ...chat.messages,
                  { id: uuidv4(), role: "assistant", content: `🚨 ${error.message || "Unable to reach the AI server."}`, timestamp: new Date() }
                ],
              }
              : chat
          ),
        }));
      }
    }
  },

  fetchChats: async () => {
    set({ isLoading: true });
    try {
      const response = await fetch("http://localhost:8000/api/chat/history");
      if (!response.ok) throw new Error("Could not fetch history");

      const historyData = await response.json();

      const syncedChats: ChatItem[] = historyData.map((chat: any) => ({
        id: chat.id,
        title: chat.title,
        messages: chat.messages.map((m: any) => ({
          id: m.id,
          role: m.role,
          content: m.content,
          timestamp: new Date(m.timestamp),
          total_tokens: m.total_tokens
        })),
        total_tokens: chat.total_tokens || 0,
        createdAt: new Date(chat.created_at || chat.updated_at),
        updatedAt: new Date(chat.updated_at)
      }));

      set({ chats: syncedChats, isLoading: false });
    } catch (error) {
      console.error("Failed to fetch chats:", error);
      toast.error("Server connection failed. Showing local history.");
      set({ isLoading: false });
    }
  },

  clearHistory: async () => {
    try {
      const response = await fetch("http://localhost:8000/api/chat/history", { method: "DELETE" });
      if (!response.ok) throw new Error("Failed to clear history");

      set({ chats: [] });
      toast.success("History cleared");
    } catch (error) {
      console.error("Failed to clear history:", error);
      toast.error("Failed to clear history on server.");
    }
  }
}));
